   3│ /// A receipt + its HMAC seal. The seal makes the receipt tamper-evident: any edit to the receipt (including
   4│ /// flipping the verdict or swapping the diffDigest) invalidates the tag unless the attacker holds the key.
   5│ public struct SealedReceipt: Codable, Equatable, Sendable {
   6│     public var receipt: VerificationReceipt
   7│     public var sealTag: String   // hex HMAC-SHA256 over receipt.canonicalBytes()
   8│     public var keyID: String     // identifies the sealing key (supports rotation)
   9│ 
  10│     public init(receipt: VerificationReceipt, sealTag: String, keyID: String) {
  11│         self.receipt = receipt; self.sealTag = sealTag; self.keyID = keyID
  12│     }
  13│ }
  14│ 
  15│ /// Seal + the ADMISSION GATE. `admit` is the single decision the git-guard / PR-check calls: it returns
  16│ /// `.admit` ONLY when all three fail-closed conditions hold, else `.reject(reason)`.
  17│ public enum ReceiptSeal {
  18│ 
  19│     public static func seal(_ receipt: VerificationReceipt, key: Data, keyID: String) -> SealedReceipt {
  20│         let tag = MythosCrypto.hmacSHA256(key: key, message: receipt.canonicalBytes())
  21│         return SealedReceipt(receipt: receipt, sealTag: ReceiptHex.encode(tag), keyID: keyID)
  22│     }
  23│ 
  24│     public enum Admission: Equatable, Sendable {
  25│         case admit
  26│         case reject(String)
  27│         public var isAdmitted: Bool { if case .admit = self { return true }; return false }
  28│     }
  29│ 
  30│     /// Admit a change for merge ONLY IF:
  31│     ///   1. the seal is intact (not forged / correct key), AND
  32│     ///   2. the receipt is bound to THIS EXACT diff (diffDigest == SHA-256 of the presented diff), AND
  33│     ///   3. the receipt verdict is `pass`.
  34│     /// Any failure ⇒ reject with a reason. Fail-closed throughout — a malformed tag, a stale/other-change
  35│     /// receipt, or a non-pass verdict all block the merge.
  36│     public static func admit(_ sealed: SealedReceipt, forDiff diff: String, key: Data) -> Admission {
  37│         guard let tag = ReceiptHex.decode(sealed.sealTag) else {
  38│             return .reject("receipt seal is malformed")
  39│         }
  40│         guard MythosCrypto.hmacSHA256Valid(key: key, message: sealed.receipt.canonicalBytes(), tag: tag) else {
  41│             return .reject("receipt seal invalid — forged, edited, or wrong key")
  42│         }
  43│         let expected = ReceiptSubject.digest(ofDiff: diff)
  44│         guard sealed.receipt.subject.diffDigest == expected else {
  45│             return .reject("receipt does not cover this change (diff digest mismatch — a receipt is only valid "
  46│                          + "for the exact diff it verified)")
  47│         }
  48│         guard sealed.receipt.verdict == .pass else {
  49│             return .reject("receipt verdict is '\(sealed.receipt.verdict.rawValue)', not 'pass'")
  50│         }
  51│         return .admit
  52│     }
  53│ }
  54│ 
  55│ /// Minimal hex codec (kept local so the receipt module has no external hex dependency).
  56│ enum ReceiptHex {
  57│     static func encode(_ data: Data) -> String { data.map { String(format: "%02x", $0) }.joined() }
  58│     static func decode(_ hex: String) -> Data? {
  59│         let chars = Array(hex)
  60│         guard chars.count % 2 == 0 else { return nil }
  61│         var out = Data(capacity: chars.count / 2)
  62│         var i = 0
  63│         while i < chars.count {
  64│             guard let byte = UInt8(String(chars[i...i+1]), radix: 16) else { return nil }
  65│             out.append(byte); i += 2
  66│         }
  67│         return out
  68│     }
  69│ }
