   3│ /// Deterministic checks that run over a change to produce ReceiptChecks — the cheap, model-independent backbone
   4│ /// of proof-carrying patches (docs/kist/LEAPFROG_ROADMAP_2026.md WS1). These run in milliseconds, locally, with
   5│ /// no LLM in the loop. `ReceiptChecks.parseAddedLines` turns a unified diff into the added-line content the
   6│ /// scans inspect; `runBuiltins` runs the security backbone; `CommandCheck` wraps compile/test as a check.
   7│ public enum ReceiptChecks {
   8│ 
   9│     /// Added (`+`) content lines from a unified diff (excludes the `+++` file header). Trims the leading `+`.
  10│     public static func parseAddedLines(_ diff: String) -> [String] {
  11│         diff.split(separator: "\n", omittingEmptySubsequences: false).compactMap { line in
  12│             guard line.hasPrefix("+"), !line.hasPrefix("+++") else { return nil }
  13│             return String(line.dropFirst())
  14│         }
  15│     }
  16│ 
  17│     /// The built-in deterministic security scans every change is checked against.
  18│     public static func runBuiltins(diff: String) -> [ReceiptCheck] {
  19│         let added = parseAddedLines(diff)
  20│         return [secretScan(added), hostControlIntro(added)]
  21│     }
  22│ 
  23│     /// Fail if a change ADDS a hard-coded secret (private key blocks, AWS keys, long bearer/base64 blobs).
  24│     static func secretScan(_ added: [String]) -> ReceiptCheck {
  25│         let patterns: [(String, String)] = [
  26│             ("private-key-block", "-----BEGIN [A-Z ]*PRIVATE KEY-----"),
  27│             ("aws-access-key", "AKIA[0-9A-Z]{16}"),
  28│             ("generic-api-key", "(?i)(api[_-]?key|secret|token)\\s*[=:]\\s*[\"']?[A-Za-z0-9_\\-]{24,}"),
  29│         ]
  30│         var hits: [String] = []
  31│         for line in added {
  32│             for (label, pat) in patterns where line.range(of: pat, options: .regularExpression) != nil {
  33│                 hits.append(label)
  34│             }
  35│         }
  36│         let ok = hits.isEmpty
  37│         return ReceiptCheck(name: "no-secrets", kind: .deterministic, passed: ok,
  38│                             detail: ok ? "no hard-coded secrets in added lines" : "possible secret(s): \(Set(hits).sorted().joined(separator: ", "))")
  39│     }
  40│ 
  41│     /// Fail if a change INTRODUCES host-control / UI-automation shell (osascript/screencapture/…) — the exact
  42│     /// capability kist's own security denies by default. Reuses the canonical host-control token list.
  43│     static func hostControlIntro(_ added: [String]) -> ReceiptCheck {
  44│         let tokens = ["osascript", "cliclick", "screencapture", "cgeventpost", "axuielement", "\"system events\""]
  45│         var hits: [String] = []
  46│         for line in added {
  47│             let l = line.lowercased()
  48│             for t in tokens where l.contains(t) { hits.append(t) }
  49│         }
  50│         let ok = hits.isEmpty
  51│         return ReceiptCheck(name: "no-host-control-intro", kind: .deterministic, passed: ok,
  52│                             detail: ok ? "no UI-automation/host-control introduced"
  53│                                        : "introduces host-control: \(Set(hits).sorted().joined(separator: ", "))")
  54│     }
